// Local report review only. No crawling, AI calls or changes to a tenant.
window.WebsiteReportsPreview = (() => {
  const e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const btn = (label, action, id='', extra='') => `<button type="button" class="button" data-wr-action="${action}" data-wr-id="${id}" ${extra}>${label}</button>`;
  const initial = () => Array.from({length:10},(_,i)=>({id:i+1,title:i===0?'تقرير متجر نواة · مثال':'تحليل توضيحي '+(i+1),url:'https://example.test/report/'+(i+1),status:i===1?'analyzing':i===2?'failed':'completed',revision:1}));
  const labels={all:'كل الحالات',pending:'بانتظار التشغيل',analyzing:'جارٍ التحليل',failed:'تعذر الإكمال',completed:'انتهى التشغيل · راجع النتائج'};
  const limitations='درجات تقديرية محفوظة للموقع؛ ليست نسبة احتراف المبيعات أو تحويل العملاء، ولا فحصًا فعليًا لآيفون وسفاري أو الأمان. قد تحتوي التقارير القديمة على أصفار افتراضية.';
  const effect='يحذف التقرير وسجلات الاستخراج واقتراحاته. تبقى منتجات الكتالوج والصفحات والأسئلة وأقسام المعرفة المستوردة. قد يتوقف ساري عن استخدام نصه كمصدر احتياطي أو يستخدم تقريرًا أقدم. تُمسح الإجابات المخزنة مؤقتًا.';
  let rows=initial(), query='', filter='all', page=1, mode='ready', outcome='success', selected=null, stale=false;
  const matches=()=>rows.filter(r=>(filter==='all'||r.status===filter)&&`${r.title} ${r.url} ${r.id}`.includes(query));
  const handles=p=>p.route==='/merchant/smart-analysis';
  function render(){
    const found=matches(), pages=Math.max(1,Math.ceil(found.length/8));page=Math.min(page,pages);
    return `<section class="wr-workspace form-stack"><div class="summary-box"><b>تقارير تحليل الموقع</b><p>${limitations}</p><p>هذه محاكاة تفصيلية للسجل والمراجعة. معاينة الاستيراد الجماعي تحتاج استكمالًا منفصلًا.</p></div>
      <div class="wr-actions"><a class="button" href="#/page/merchant/sari-brain">مراجعة الصفحات والأسئلة في عقل ساري</a>${btn('تحليل وتحديث المعرفة','start','',''+(['readonly','error','loading'].includes(mode)?'disabled':''))}</div>
      <div class="wr-controls"><label>حالة المعاينة<select id="wr-mode">${['ready','readonly','error','empty','loading'].map((v,i)=>`<option value="${v}" ${mode===v?'selected':''}>${['بيانات محفوظة','قراءة فقط','فشل القراءة','لا توجد نتائج','تحميل'][i]}</option>`).join('')}</select></label><label>نتيجة الحذف<select id="wr-outcome">${['success','failure','conflict'].map((v,i)=>`<option value="${v}" ${outcome===v?'selected':''}>${['نجاح','نتيجة غير مؤكدة','تغير التقرير'][i]}</option>`).join('')}</select></label></div>
      <form class="wr-controls" data-wr-search><label>ابحث بالعنوان أو الرابط أو الرقم<input name="search" value="${e(query)}" maxlength="200"></label><label>الحالة<select name="filter">${Object.entries(labels).map(([v,s])=>`<option value="${v}" ${filter===v?'selected':''}>${s}</option>`).join('')}</select></label><button class="button" type="submit">بحث</button>${btn('تحديث','refresh')}</form>
      ${mode==='error'?'<p role="alert">تعذر تحميل التقارير. لا يعني ذلك عدم وجود بيانات.</p>':mode==='loading'?'<p role="status">جارٍ تحميل التقارير…</p>':mode==='empty'||!found.length?'<p role="status">لا توجد تقارير تطابق البحث.</p>':`${mode==='readonly'?'<p>للقراءة فقط: الإدارة تتطلب صلاحية إعدادات المساعد.</p>':''}<p>التقارير المطابقة: ${found.length}</p><div class="wr-grid">${found.slice((page-1)*8,page*8).map(r=>`<article class="panel panel-pad"><h3>${e(r.title)}</h3><p dir="ltr">${e(r.url)}</p><p>#${r.id} · ${labels[r.status]}</p>${btn('مراجعة التقرير #'+r.id,'review',r.id)}</article>`).join('')}</div><nav class="wr-actions" aria-label="صفحات التقارير">${btn('السابق','previous','',page===1?'disabled':'')}<span>${page} / ${pages}</span>${btn('التالي','next','',page===pages?'disabled':'')}</nav>`}</section>`;
  }
  function review(id){
    const r=rows.find(r=>r.id===Number(id));if(!r)return;selected={id:r.id,revision:r.revision};stale=false;
    const running=r.status==='analyzing'||r.status==='pending';
    openDialog('مراجعة التقرير #'+r.id,`<div class="wr-review"><div class="wr-review-body form-stack"><h3>${e(r.title)}</h3><p dir="ltr">${e(r.url)}</p><p>${labels[r.status]}</p><p>${limitations}</p>${running?'<p role="status">التحليل لم ينتهِ. الدرجات والحذف غير متاحين؛ تحديث العرض لا يلغي التشغيل.</p>':r.status==='failed'?'<p role="alert">النتائج جزئية؛ راجع المعرفة والمنتجات المحفوظة.</p>':''}<dl class="wr-grid">${['التقدير العام','الظهور في البحث','الأداء','سهولة الاستخدام','المحتوى'].map((s,i)=>`<div class="summary-box"><dt>${s}</dt><dd>${r.status==='completed'?[72,80,60,75,73][i]+'/100':'غير متاح'}</dd></div>`).join('')}</dl><details><summary>نص المصدر المحفوظ</summary><p>${e('نص توضيحي محفوظ — <script>نص غير منفّذ</script>')}</p></details><details><summary>ملاحظات الظهور في البحث والبيانات المحفوظة</summary><p>بعض المنتجات تفتقد وصفًا فريدًا. لغة الصفحة: العربية. هذا مثال، وليس نتيجة فحص الموقع.</p></details><details><summary>سجلات المنتجات المستخرجة (1)</summary><p>عينة تعريفية · السعر المسجل 0.00 SAR · متوفرة</p><p>قد تختلف هذه السجلات عن الكتالوج الحالي.</p></details><details><summary>الاقتراحات (1)</summary><h3>وضّح سياسة الاسترجاع</h3><p>أضف شروطًا معتمدة ومحددة بدل ضمانات عامة. الأثر المتوقع تقديري.</p></details><p id="wr-error" role="alert"></p><div id="wr-delete-review">${!running&&mode!=='readonly'?`<p>${effect}</p><label class="check-label"><input type="checkbox" id="wr-ack"><span>راجعت التقرير وفهمت أثر الحذف.</span></label>${btn('حذف التقرير المراجع','delete',r.id,'disabled')}`:''}</div></div><footer class="wr-actions wr-footer">${btn('إغلاق','close')}${btn('تحديث المراجعة','reread',r.id)}${btn('تصدير JSON توضيحي','export',r.id)}</footer></div>`);
  }
  function start(){if(['readonly','error','loading'].includes(mode))return;openDialog('مراجعة نطاق التحليل الكامل',`<form class="form-stack" data-wr-start><p>في التطبيق، تزور هذه العملية الموقع وتستخدم خدمات الذكاء الاصطناعي، وقد تعدّل معرفة مفعلة وصفحات وأسئلة ومنتجات وبيانات التواصل قبل اكتمالها. قد تبقى تحديثات جزئية عند الفشل. معاينة الاستيراد لا تشغّل هذه العملية.</p><label>رابط الموقع العام<input required name="url" type="url" maxlength="500" dir="ltr" placeholder="https://example.test"></label><label class="check-label"><input required type="checkbox" name="ack"><span>أوافق على أثر هذه العملية في المثال.</span></label><p id="wr-start-error" role="alert"></p><footer class="wr-actions"><button type="submit" class="button primary">بدء محاكاة محلية</button>${btn('إغلاق','close')}</footer></form>`);}
  document.addEventListener('change',event=>{const el=event.target;if(el.id==='wr-ack'){document.querySelector('[data-wr-action=delete]').disabled=!el.checked||stale;return;}if(el.id==='wr-outcome'){outcome=el.value;return;}if(el.id==='wr-mode'){mode=el.value;window.render();document.getElementById('wr-mode')?.focus();}});
  document.addEventListener('submit',event=>{const form=event.target;if(form.matches('[data-wr-search]')){event.preventDefault();query=form.elements.search.value.trim();filter=form.elements.filter.value;page=1;window.render();}if(form.matches('[data-wr-start]')){event.preventDefault();let url;try{url=new URL(form.elements.url.value);}catch{return;}if(!form.elements.ack.checked||!['https:','http:'].includes(url.protocol)||url.username||url.password){document.getElementById('wr-start-error').textContent='راجع الرابط والموافقة.';return;}rows.unshift({id:Math.max(...rows.map(r=>r.id),0)+1,title:'محاكاة تحليل جارٍ',url:url.href,status:'analyzing',revision:1});mode='ready';page=1;query='';filter='all';document.getElementById('dialog').close();window.render();}});
  document.addEventListener('click',event=>{const el=event.target.closest('[data-wr-action]');if(!el)return;const {wrAction:a,wrId:id}=el.dataset;
    if(a==='close'){document.getElementById('dialog').close();return;}
    if(a==='start'){start();return;}
    if(a==='refresh'){mode='ready';window.render();return;}
    if(a==='review'||a==='reread'){review(id);return;}
    if(a==='previous'||a==='next'){page+=a==='next'?1:-1;window.render();return;}
    if(a==='delete'){
      const r=rows.find(r=>r.id===Number(id));if(!r||stale||!document.getElementById('wr-ack')?.checked||mode==='readonly'||r.status==='analyzing')return;
      if(outcome!=='success'||selected?.revision!==r.revision){stale=true;if(outcome==='conflict')r.revision++;document.getElementById('wr-error').textContent=outcome==='conflict'?'تغير التقرير؛ حدّث المراجعة ووافق مجددًا.':'تعذر تأكيد الحذف؛ حدّث المراجعة قبل المحاولة.';document.getElementById('wr-delete-review').innerHTML='';document.querySelector('[data-wr-action=export]').disabled=true;return;}
      rows=rows.filter(row=>row.id!==r.id);document.getElementById('dialog').close();window.render();return;
    }
    if(a==='export'&&!stale){const r=rows.find(r=>r.id===Number(id));const url=URL.createObjectURL(new Blob([JSON.stringify({example:true,limitations,...r},null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='example-report-'+id+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  });
  return {handles,render,primary:start};
})();
